insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('80dfedd4-ca1c-47bb-90c5-912ca05ff0b3', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$uit een krant, januari 2020$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context1.png$$,
   $$Uit een krant, januari 2020:$$, 'inline'),
  ('44d2fe42-2878-4455-94d9-59ba11fce21e', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$vakbonden eisen 3,5% loonsverhoging met een minimale stijging van € 1.000$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context2.png$$,
   $$Het gaat economisch goed in Nederland. De overgrote meerderheid van de bedrijven presenteert goede winstcijfers. De landelijke supermarktketens onderhandelen met de vakbonden over een nieuwe collectieve arbeidsovereenkomst (cao). De vakbonden eisen 3,5% loonsverhoging op het jaarsalaris, met een minimale stijging van € 1.000.$$, 'inline'),
  ('efc62029-c185-499c-b3ae-b38fab87b1c7', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$Els Middelkoop verdiende in 2019 een jaarsalaris van € 24.998$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context3.png$$,
   $$Els Middelkoop is medewerker van een supermarkt. Ze leest in de krant over de looneis van de vakbond. Els verdiende in 2019 een jaarsalaris van € 24.998,- en is benieuwd naar wat dit in 2020 voor haar zou betekenen.$$, 'inline'),
  ('3a1fbebf-b0f8-48c3-9615-7ead8159212c', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$onderhandelaars van supermarktketens en vakbond bespreken de looneis$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context4.png$$,
   $$Barbara Berends is onderhandelaar van de supermarktketens, en Jacco Jansen is onderhandelaar van de vakbond. Samen bespreken zij de consequenties van de loonstijging die door de vakbond geëist is. De onderhandelaar van de werkgever vindt de looneis te hoog.$$, 'inline'),
  ('2933ca1e-7cf8-4717-af6d-7abed2babe5b', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$loonkosten 40% van de totale kosten; drie uitspraken van Jacco Jansen$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context5.png$$,
   $$Barbara Berends: “U moet zich realiseren dat een loonkostenstijging van 3,5% binnen ons bedrijf, waar de loonkosten 40% van de totale kosten uitmaken, zal leiden tot een productiekostenstijging van 1,4%. De supermarktketens kunnen deze hoge looneis niet betalen.” Jacco Jansen reageert met de volgende uitspraken:
1 U spreekt over de nominale productiekostenstijging, maar de reële productiekostenstijging is lager.
2 Bovendien leidt de gestegen arbeidsproductiviteit tot lagere productiekosten.
3 En u moet zich realiseren dat de omzet bij supermarkten toch zal stijgen, aangezien is gebleken dat de vraag naar goederen uit de supermarkt prijsinelastisch is.$$, 'inline'),
  ('c778ef4d-7d5a-4f25-af66-9746e93c3b4a', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$de supermarktketens gaan akkoord met de looneis; de cao geldt voor alle werknemers$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context6.png$$,
   $$Na intensieve onderhandelingen gaan de supermarktketens akkoord met de looneis van de vakbond. De nieuwe cao geldt voor alle werknemers.$$, 'inline'),
  ('00dd1e3c-bc57-45ad-a234-4a78f589cc8a', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$de gegevens bij deze opgave zijn representatief voor de supermarktbranche$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context7.png$$,
   $$De gegevens bij deze opgave zijn representatief voor de supermarktbranche.$$, 'inline'),
  ('16c1d275-a6c5-4032-8451-cf62760815c5', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$bron 1: jaarlijkse ontwikkeling van de inflatie en de arbeidsproductiviteit$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context8.png$$,
   $$Bron 1 Jaarlijkse ontwikkeling van de inflatie en de arbeidsproductiviteit (procentuele verandering ten opzichte van het voorgaande jaar)
jaar | inflatie | arbeidsproductiviteit
2015 | 0,3 | 0,9
2016 | 0,2 | 1,5
2017 | 0,1 | 0,4
2018 | 1,3 | 1,6
2019 | 1,6 | 1,4
2020 | 2,3 | 1,3$$, 'inline'),
  ('c4a65b8d-9a49-4f3f-a4a4-48d1aa018356', 'ce658e40-01b3-4825-ac77-04bc5ba74777', $$bron 2: percentage werknemers dat georganiseerd is via een vakbond$$,
   $$economie-havo-2024-i-een-nieuwe-cao-context9.png$$,
   $$Bron 2 Percentage werknemers dat georganiseerd is via een vakbond
(staafdiagram organisatiegraad in % voor 1980, 1990, 2000, 2010 en 2020; de organisatiegraad daalt van ruim 30% in 1980 tot onder de 20% in 2020)$$, 'inline'),
  ('161da2ea-d368-43b4-b861-55283307d3c6', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$een speedpedelec rijdt tot 45 km/u; een helm is verplicht$$,
   $$economie-havo-2024-i-speedpedelec-context1.png$$,
   $$Een speedpedelec is een variant van de elektrische fiets die tot
45 kilometer per uur kan rijden. Bestuurders van speedpedelecs zijn verplicht om een helm te dragen.$$, 'inline'),
  ('213d1ae4-9b25-46b8-9b5e-c61e893cd194', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$de drie grootste aanbieders hebben 70% van de markt; keuzemogelijkheden in het assortiment$$,
   $$economie-havo-2024-i-speedpedelec-context2.png$$,
   $$De drie grootste aanbieders van speedpedelecs hebben gezamenlijk 70% van de markt van speedpedelecs in handen. Iedere aanbieder heeft binnen het assortiment keuzemogelijkheden, zoals design, vermogen en sterkte van de accu.$$, 'inline'),
  ('731bb84a-92bf-4349-861d-de90ee5881f9', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$gegevens Sprinter4: MK € 3.500, TCK € 1.000.000$$,
   $$economie-havo-2024-i-speedpedelec-context3.png$$,
   $$Sprinter is een van de aanbieders van speedpedelecs. Over type Sprinter4 zijn de volgende gegevens bekend: Marginale kosten (MK) € 3.500 Totale constante kosten (TCK) € 1.000.000$$, 'inline'),
  ('87cae698-c5f0-434d-a4cf-93f1f6ef02a4', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$accountantskantoor Snel: budget € 6.000 per medewerker en de spelregels voor het prijsvoorstel$$,
   $$economie-havo-2024-i-speedpedelec-context4.png$$,
   $$Sprinter heeft een nieuwe zakelijke klant gevonden. Het Nederlandse accountantskantoor Snel krijgt van het internationale moederbedrijf een budget van € 6.000 per medewerker, om voor alle 100 medewerkers speedpedelecs Sprinter4 aan te schaffen. Het moederbedrijf van Snel heeft de spelregels bepaald:
− Snel doet een prijsvoorstel aan Sprinter voor levering van 100 stuks Sprinter4. Dat voorstel kan € 6.000 per speedpedelec zijn, maar het kan ook een lager bedrag zijn.
− Als Sprinter het voorstel accepteert, dan ontvangt Sprinter de afgesproken prijs en ontvangt Snel het verschil tussen € 6.000 en de afgesproken prijs.
− Als Sprinter het voorstel weigert, dan ontvangen beide bedrijven niets. Sprinter wil minimaal € 3.500 ontvangen voor type Sprinter4.$$, 'inline'),
  ('ec2e2fb6-e371-4ff7-82ad-55df76c358a0', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$de spelregels voldoen aan de kenmerken van een ultimatumspel$$,
   $$economie-havo-2024-i-speedpedelec-context5.png$$,
   $$De hiervoor vermelde spelregels voldoen aan de kenmerken van een ultimatumspel.$$, 'inline'),
  ('7fcce557-b58f-44d5-99e7-581a5203fcdb', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$bron 2 beschrijft drie keuzeopties in een beslisboom$$,
   $$economie-havo-2024-i-speedpedelec-context6.png$$,
   $$In bron 2 staan drie keuzeopties van het spel beschreven in een beslisboom. De uitkomsten geven de verdeling van het restbedrag na aftrek van de variabele productiekosten.$$, 'inline'),
  ('aef67401-0f7b-4d9e-a054-64e8aafdf9f8', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$Snel wil € 3.700 bieden; waarschuwing van een deskundige over ultimatumspellen$$,
   $$economie-havo-2024-i-speedpedelec-context7.png$$,
   $$De directie van Snel wil Sprinter een prijsvoorstel doen van € 3.700 per speedpedelec. Een deskundige op het gebied van ultimatumspellen waarschuwt: “Snel kan beter een hoger bod doen aan Sprinter, want de praktijk leert dat zo’n laag bod toch vaak geweigerd wordt, ondanks dat beide bedrijven dan niets ontvangen.”$$, 'inline'),
  ('834ebcaa-3ca5-4049-8ace-a8662a698f0b', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$bron 1: kosten en opbrengsten voor speedpedelecs Sprinter4$$,
   $$economie-havo-2024-i-speedpedelec-context8.png$$,
   $$Bron 1 Kosten en opbrengsten voor speedpedelecs Sprinter4
(grafiek: verticaal € (x 1.000), horizontaal q (x 100 stuks); GO daalt van F (12) via G, H en J; MO daalt van F naar P (q = 5); MK is horizontaal op A (3,5); GTK daalt via G, I en K; M = snijpunt MO en MK bij N (q = 3,5); hulppunten B, C, D, E op de verticale as en L op MK bij q = 5)
GTK = gemiddelde totale kosten
GO = gemiddelde opbrengst
MO = marginale opbrengst
MK = marginale kosten$$, 'inline'),
  ('0d9f604b-07c6-4e0c-b78a-9baf08b1c0f3', '7b9ecbe1-96c2-4bdb-b61d-c51b857c1f89', $$bron 2: beslisboom prijsvoorstel Snel aan Sprinter$$,
   $$economie-havo-2024-i-speedpedelec-context9.png$$,
   $$Bron 2 Beslisboom prijsvoorstel Snel aan Sprinter
Snel → prijsvoorstel € 6.000 → Sprinter accepteren: € 0 ; € 2.500
Snel → prijsvoorstel € 4.500 → Sprinter accepteren: …(1)… ; …(2)… / weigeren: € 0 ; € 0
Snel → prijsvoorstel € 3.501 → Sprinter accepteren: € 2.499 ; € 1 / weigeren: € 0 ; € 0
De opbrengsten rechts in de spelboom geven de verdeling van het restbedrag na aftrek van de variabele productiekosten.$$, 'inline'),
  ('fd3d0e3c-a952-4e8f-8832-33eca6386eb4', '0da828f0-05b4-4221-bf21-f8f762cc3d7f', $$uit een krant$$,
   $$economie-havo-2024-i-een-valse-start-context1.png$$,
   $$Uit een krant:$$, 'inline'),
  ('40c4bfc4-c0f0-4fb4-98ed-2ce0631d9e0d', '0da828f0-05b4-4221-bf21-f8f762cc3d7f', $$starters op de woningmarkt huren vaak eerst in de vrije sector; groeiende vermogensongelijkheid$$,
   $$economie-havo-2024-i-een-valse-start-context2.png$$,
   $$De huizenprijzen zijn in 2021 op een hoogtepunt na een lange periode van sterke prijsstijgingen. Nieuwkomers op de woningmarkt, ook wel starters genoemd, hebben nog geen vermogen opgebouwd en moeten de aankoop van een woning volledig financieren met een lening. Starters met een modaal inkomen kiezen er vaak voor om eerst een woning in de vrije sector te huren, voordat ze besluiten om een woning te kopen. In de vrije sector van de huurwoningenmarkt geldt geen maximale huurprijs. De woonlasten van deze huurders zijn doorgaans hoger dan de woonlasten van kopers van een vergelijkbare woning. Daarnaast groeit het vermogen van huurders niet mee met de stijging van de huizenprijzen. Hierdoor ontstaat een groeiende vermogensongelijkheid tussen kopers en huurders. Dat zorgt ervoor dat een toekomstige stap van huur naar koop alleen maar lastiger wordt.$$, 'inline'),
  ('6b69922f-ddba-4716-9a3e-41e4d5e72af8', '0da828f0-05b4-4221-bf21-f8f762cc3d7f', $$het marginale tarief van de hypotheekrenteaftrek wordt afgebouwd van 49,50% naar 37,05%$$,
   $$economie-havo-2024-i-een-valse-start-context3.png$$,
   $$Woningbezitters mogen de betaalde hypotheekrente aftrekken van de inkomstenbelasting. Dit belastingvoordeel bevordert eigenwoningbezit, en belemmert een goed functionerende verhuurmarkt. De overheid wil een evenwichtige woningmarkt bevorderen, en past daarom de tarieven van de hypotheekrenteaftrek aan. Zo wordt het marginale belastingtarief waartegen de hypotheekrente maximaal kan worden afgetrokken geleidelijk afgebouwd van 49,50% naar 37,05%.$$, 'inline'),
  ('debdf7b9-102c-4647-acf4-a04bd4b87669', '0da828f0-05b4-4221-bf21-f8f762cc3d7f', $$tabel: marginaal tarief hypotheekrenteaftrek nu en na afbouw$$,
   $$economie-havo-2024-i-een-valse-start-context4.png$$,
   $$belastbaar inkomen | marginaal tarief hypotheekrenteaftrek nu | na afbouw
€ 0 - € 69.398 | 37,05% | 37,05%
€ 69.399 en hoger | 49,50% | 37,05%$$, 'inline'),
  ('f922c3f3-b7a7-4cab-9a82-2776dd76339c', '0da828f0-05b4-4221-bf21-f8f762cc3d7f', $$twee uitspraken van een econoom over de tariefaanpassing$$,
   $$economie-havo-2024-i-een-valse-start-context5.png$$,
   $$Een econoom doet naar aanleiding van de tariefaanpassing twee uitspraken: Uitspraak 1: “Door de tariefaanpassing wordt de secundaire inkomensverdeling gelijker.” Uitspraak 2: “Op de lange termijn kan de tariefaanpassing bijdragen aan de betaalbaarheid van koopwoningen.”$$, 'inline'),
  ('01a69540-b723-4c04-af24-3216dff3d293', '4102946d-211f-4001-b57b-3e7e956a23b9', $$uit een krant$$,
   $$economie-havo-2024-i-pensioenuitkeringen-context1.png$$,
   $$Uit een krant:$$, 'inline'),
  ('297d6a36-bf2d-4d17-9772-804a8f04b0fb', '4102946d-211f-4001-b57b-3e7e956a23b9', $$ABP: € 456 miljard in kas; dekkingsgraad daalt van 94 naar 89 procent$$,
   $$economie-havo-2024-i-pensioenuitkeringen-context2.png$$,
   $$Het pensioenfonds ABP behaalde in augustus een beleggingswinst van € 5 miljard uit onder meer aandelen, vastgoed en obligaties. Daardoor had het fonds eind augustus € 456 miljard in de pensioenkas. De huidige waarde van de toekomstige verplichtingen van het ABP groeide echter veel harder. Bij het ABP daalde de dekkingsgraad1) in augustus van 94 naar 89 procent. Dat betekent dat het ABP te weinig vermogen heeft om de toekomstige uitkeringen te kunnen uitbetalen. De Nederlandsche Bank (DNB) is de toezichthouder op de pensioenfondsen en berekent de huidige waarde van de toekomstige verplichtingen op basis van de rentestand.$$, 'inline'),
  ('cdcfdedb-442f-4c5a-8ec5-f6600ed4ef9c', '4102946d-211f-4001-b57b-3e7e956a23b9', $$noot: definitie dekkingsgraad$$,
   $$economie-havo-2024-i-pensioenuitkeringen-context3.png$$,
   $$¹⁾ Dekkingsgraad = (huidige vermogen pensioenfonds / huidige waarde toekomstige verplichtingen pensioenfonds) x 100%$$, 'inline'),
  ('acd505c6-e394-4fff-9d63-4d5fab743511', '4102946d-211f-4001-b57b-3e7e956a23b9', $$door de lage dekkingsgraad moeten pensioenuitkeringen mogelijk worden verlaagd$$,
   $$economie-havo-2024-i-pensioenuitkeringen-context4.png$$,
   $$Als gevolg van de lage dekkingsgraad is de kans groot dat de huidige en toekomstige pensioenuitkeringen moeten worden verlaagd.$$, 'inline'),
  ('bcc6e58f-ffff-48f7-863c-c40f8273200a', '4102946d-211f-4001-b57b-3e7e956a23b9', $$bedrijfspensioenen via kapitaaldekkingsstelsel, AOW via omslagstelsel; lage rente$$,
   $$economie-havo-2024-i-pensioenuitkeringen-context5.png$$,
   $$Het huidige pensioenstelsel bestaat uit bedrijfspensioenen, die via het kapitaaldekkingsstelsel gefinancierd worden, en uit AOW-uitkeringen, die via het omslagstelsel gefinancierd worden. In periodes van lage rente verslechtert de betaalbaarheid van het kapitaaldekkingsstelsel.$$, 'inline'),
  ('188a1e8f-936c-416f-99b5-3b52b31ac1fa', '072cce8d-ecaa-4d13-a161-6c9048232ac7', $$bestedingen in de sector toerisme nemen toe; driekwart door buitenlandse toeristen$$,
   $$economie-havo-2024-i-toerisme-context1.png$$,
   $$De wereldbevolking blijft groeien. Bovendien zijn er, mede door lagere prijzen, steeds meer mensen in staat om vaker en langer te reizen. De bestedingen in de sector toerisme nemen daardoor wereldwijd toe. Ook in Nederland leveren hogere bestedingen in deze sector in toenemende mate een bijdrage aan het bruto binnenlands product (bbp) en de werkgelegenheid. Driekwart van de bestedingen in de sector toerisme is te danken aan de bestedingen van buitenlandse toeristen in Nederland.$$, 'inline'),
  ('6017e89b-b41d-4144-9fe1-8b0197dd0ddb', '072cce8d-ecaa-4d13-a161-6c9048232ac7', $$bron 1 laat de werkgelegenheid in personen en arbeidsjaren zien$$,
   $$economie-havo-2024-i-toerisme-context2.png$$,
   $$Bron 1 laat de werkgelegenheid in de sector toerisme zien, zowel in aantal personen als in arbeidsjaren. Beide indicatoren zijn toegenomen als gevolg van de toegenomen bestedingen in de sector. Ook wordt er minder in deeltijd gewerkt.$$, 'inline'),
  ('225b4b3b-f702-4d7f-b7cb-f55e99292f31', '072cce8d-ecaa-4d13-a161-6c9048232ac7', $$concentratie van toerisme leidt tot negatieve externe effecten$$,
   $$economie-havo-2024-i-toerisme-context3.png$$,
   $$Op plekken in Nederland waar het toerisme zich vooral concentreert, treden negatieve externe effecten op.$$, 'inline'),
  ('0c31cadf-1a31-4bb2-a919-7b77a8bede78', '072cce8d-ecaa-4d13-a161-6c9048232ac7', $$adviesbureau pleit voor prijsdiscriminatie in het openbaar vervoer voor buitenlandse toeristen$$,
   $$economie-havo-2024-i-toerisme-context4.png$$,
   $$Adviesbureau De Toerist heeft onderzocht hoe het toerisme beter kan worden gespreid over het hele land. Het blijkt dat buitenlandse toeristen in Nederland relatief weinig met het openbaar vervoer reizen. Het adviesbureau pleit ervoor om buitenlandse toeristen via prijsdiscriminatie aan te zetten tot meer gebruik van het openbaar vervoer.$$, 'inline'),
  ('311e5c3e-6558-49fe-a4c6-7e73a873053a', '072cce8d-ecaa-4d13-a161-6c9048232ac7', $$bron 1: werkgelegenheid in de sector toerisme 2014-2017$$,
   $$economie-havo-2024-i-toerisme-context5.png$$,
   $$Bron 1 Werkgelegenheid in de sector toerisme 2014 - 2017 (x 1000)
jaar | werkgelegenheid in personen | werkgelegenheid in arbeidsjaren*)
2014 | 703 | 413
2015 | 718 | 423
2016 | 732 | 435
2017 | 761 | 455
*) Een arbeidsjaar is een maatstaf voor het arbeidsvolume. Dit wordt berekend door alle banen (voltijd en deeltijd) om te rekenen naar voltijdbanen. Bijvoorbeeld: twee halve banen (allebei 50% van een volledige baan), leveren samen 1 arbeidsjaar op.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('15ca82a1-07cf-4bae-86d6-56f2384faaa7', 'ce658e40-01b3-4825-ac77-04bc5ba74777', 1,
   '[{"domain": "Welvaart en groei", "subdomain": "Ongelijkheid en herverdeling"}, {"domain": "Markt", "subdomain": "Arbeidsmarkt"}]'::jsonb,
   '["nivelleren", "looneis", "minimale loonstijging", "procentuele loonstijging", "inkomensverschillen"]'::jsonb,
   $$Uitleggen dat een looneis met een minimumbedrag nivellerend werkt.$$,
   $$economie-havo-2024-i-een-nieuwe-cao-vraag1.png$$, $$2p 1 Leg uit dat er sprake is van nivelleren, als de looneis van de vakbond wordt ingewilligd.$$, array['80dfedd4-ca1c-47bb-90c5-912ca05ff0b3', '44d2fe42-2878-4455-94d9-59ba11fce21e']::uuid[]),
  ('3ca730d5-df4f-4283-a8a3-c5bb8eca6e21', 'ce658e40-01b3-4825-ac77-04bc5ba74777', 2,
   '[{"domain": "Markt", "subdomain": "Arbeidsmarkt"}, {"domain": "Goede tijden, slechte tijden", "subdomain": "Conjunctuur en conjuncturele verschijnselen"}]'::jsonb,
   '["koopkracht berekenen", "reëel inkomen", "inflatie", "nominale loonstijging"]'::jsonb,
   $$De koopkrachtverandering berekenen uit de nominale loonstijging en de inflatie.$$,
   $$economie-havo-2024-i-een-nieuwe-cao-vraag2.png$$, $$Gebruik het krantenbericht en bron 1.
